import{_ as i,o as l,c as e,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-11-15","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-11-15","date":"2023-11-15T00:00:00.000Z","updated":"2023-11-21T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","数据模型","配置初始化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-11-15.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-11-15.md","lastUpdated":1780460162000}'),r={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-11-15.md"};function o(n,t,s,g,_,p){return l(),e("div",null,[...t[0]||(t[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概览" tabindex="-1">会议概览 <a class="header-anchor" href="#会议概览" aria-label="Permalink to &quot;会议概览&quot;">​</a></h4><p>本次会议主要讨论了Ceph分布式存储系统中的RGW（Rados Gateway）组件的多个技术议题，包括通知数据模型的更新、生命周期与复制管理、动态重分片策略以及配置初始化等。会议涉及了技术细节的深入探讨、解决方案的提出以及后续行动计划的制定。</p><h4 id="主要议题与讨论" tabindex="-1">主要议题与讨论 <a class="header-anchor" href="#主要议题与讨论" aria-label="Permalink to &quot;主要议题与讨论&quot;">​</a></h4><ol><li><p><strong>通知数据模型的更新</strong></p><ul><li><strong>讨论内容</strong>：讨论了多站点通知数据模型的更新，特别是从旧数据模型迁移到新数据模型的策略。提出了多种迁移方案，包括支持两种数据模型的代码路径、迁移过程的自动化等。</li><li><strong>决定事项</strong>：建议在升级完成后进行迁移，使用新的区域组特性来全局启用新格式，并在迁移过程中发出警告以确保管理员注意到旧配置的使用。</li><li><strong>后续行动</strong>：将详细讨论和更新记录在Gist中，并考虑在Slack频道中进一步讨论。</li></ul></li><li><p><strong>生命周期与复制</strong></p><ul><li><strong>讨论内容</strong>：探讨了生命周期事件日志记录的问题，特别是对象版本化带来的挑战。讨论了是否应停止对非版本化桶的日志记录。</li><li><strong>决定事项</strong>：建议首先停止对非版本化桶的日志记录，并考虑增加智能生命周期规则以根据版本化状态进行不同的日志记录。</li><li><strong>后续行动</strong>：Jan将接手此问题，并进一步探讨解决方案。</li></ul></li><li><p><strong>动态重分片</strong></p><ul><li><strong>讨论内容</strong>：讨论了动态重分片中减少分片数量的需求，提出了在重分片队列中添加时间戳以延迟执行的方案。</li><li><strong>决定事项</strong>：建议通过配置选项来控制时间延迟和分片因子，并考虑在桶创建API中添加分片计数字段。</li><li><strong>后续行动</strong>：Eric将继续探讨此方案，并在后续会议中进一步讨论。</li></ul></li><li><p><strong>配置初始化</strong></p><ul><li><strong>讨论内容</strong>：讨论了如何在区域创建时初始化存储过滤器的配置，以及JSON配置的具体格式。</li><li><strong>决定事项</strong>：建议使用标准JSON字段“type”来加载相应的驱动程序，并递归解析JSON块。</li><li><strong>后续行动</strong>：Ali将继续进行相关开发工作，并考虑在后续PR中进行合并。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>更新和记录通知数据模型的讨论细节，并在Slack频道中进一步讨论。</li><li>Jan接手生命周期与复制问题的解决方案探讨。</li><li>Eric继续探讨动态重分片方案，并在后续会议中讨论。</li><li>Ali继续进行配置初始化的开发工作，并考虑在后续PR中进行合并。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>提醒与会者加入Slack频道，以便更好地讨论开发相关事宜。</li><li>下次会议时间：下周。</li></ul>',9)])])}const d=i(r,[["render",o]]);export{h as __pageData,d as default};
